CREATE EXTENSION IF NOT EXISTS pgcrypto; CREATE SEQUENCE IF NOT EXISTS order_number_seq START 101;
CREATE TABLE roles(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,phone TEXT,role_id INT REFERENCES roles(id),active BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE menu_categories(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,position INT DEFAULT 0);CREATE TABLE menu_items(id SERIAL PRIMARY KEY,category_id INT REFERENCES menu_categories(id),name TEXT NOT NULL,description TEXT,price NUMERIC(10,2) NOT NULL CHECK(price>=0),image_url TEXT,available BOOLEAN DEFAULT true,bestseller BOOLEAN DEFAULT false,vegetarian BOOLEAN DEFAULT false,preparation_minutes INT DEFAULT 10,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE inventory_items(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,quantity NUMERIC(10,2) NOT NULL DEFAULT 0,unit TEXT NOT NULL,low_stock_threshold NUMERIC(10,2) NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE orders(id BIGSERIAL PRIMARY KEY,order_number TEXT UNIQUE NOT NULL,order_type TEXT NOT NULL CHECK(order_type IN('EAT HERE','TAKE PARCEL')),total NUMERIC(10,2) NOT NULL,status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','preparing','completed','cancelled')),created_at TIMESTAMPTZ DEFAULT NOW(),preparation_started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ);CREATE INDEX orders_status_idx ON orders(status,created_at DESC);CREATE TABLE order_items(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id) ON DELETE CASCADE,menu_item_id INT REFERENCES menu_items(id),item_name TEXT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),unit_price NUMERIC(10,2) NOT NULL,customizations JSONB DEFAULT '{}');
